@@ -0,0 +1,31 @@
+// Sites: the kitchens Larder serves. Every location belongs to one site, and
+// a batch belongs to the site of its location. Items, suppliers, recipes and
+// dishes are shared by all sites.
+import { AppError } from "../errors.js";
+
+/** The site used when a request does not name one. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in list order. */
+export function listSites(store) {
+  return [...(store.data.sites ?? [])];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** True when location `id` exists and (if `site` is given) belongs to that site. */
+export function locationInSite(store, id, site) {
+  return store.data.locations.some((l) => l.id === id && (site === undefined || l.site === site));
+}
+
+/** A filter for batches in `site`; with no site every batch passes. */
+export function batchInSite(store, site) {
+  if (site === undefined) return () => true;
+  const ids = new Set(store.data.locations.filter((l) => l.site === site).map((l) => l.id));
+  return (b) => ids.has(b.location);
+}
