@@ -0,0 +1,124 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const ANNEX = { "X-Larder-Site": "annex" };
+
+// Puts stock in the annex: a sent order for 3 kg onion received into the annex fridge.
+async function stockAnnex(handle) {
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, headers: ANNEX, body: { lots: [{ lot: "AX-1", expires: "2026-10-30", location: "annex-fridge" }] } });
+  assert.equal(res.status, 200);
+  return res.body.batches[0];
+}
+
+test("the seed has two sites and every location has one", async () => {
+  const { store } = app();
+  assert.deepEqual(store.data.sites.map((s) => s.id), ["main", "annex"]);
+  assert.ok(store.data.locations.every((l) => store.data.sites.some((s) => s.id === l.site)));
+  assert.deepEqual(store.data.locations.find((l) => l.id === "annex-fridge"), { id: "annex-fridge", name: "Annex fridge", tempC: 4, site: "annex" });
+});
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "attic" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /attic/);
+});
+
+test("no header means main; the header name is case-insensitive", async () => {
+  const { handle } = app();
+  const plain = (await handle({ path: "/items" })).body;
+  const main = (await handle({ path: "/items", headers: { "x-larder-site": "main" } })).body;
+  assert.deepEqual(plain, main);
+  assert.equal(plain.find((i) => i.id === 1).onHand, 10);
+  const annex = (await handle({ path: "/items", headers: { "x-larder-site": "annex" } })).body;
+  assert.equal(annex.length, plain.length);
+  assert.ok(annex.every((i) => i.onHand === 0));
+});
+
+test("batches and stock on hand only show the request's site", async () => {
+  const { handle } = app();
+  const batch = await stockAnnex(handle);
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body.map((b) => b.id), [batch.id]);
+  assert.ok(!(await handle({ path: "/batches" })).body.some((b) => b.id === batch.id));
+  assert.equal((await handle({ path: `/batches/${batch.id}` })).status, 404);
+  assert.equal((await handle({ path: `/batches/${batch.id}`, headers: ANNEX })).status, 200);
+  assert.equal((await handle({ path: "/batches/1", headers: ANNEX })).status, 404);
+  assert.equal((await handle({ path: "/items/1", headers: ANNEX })).body.onHand, 3);
+  assert.equal((await handle({ path: "/items/1" })).body.onHand, 10);
+  const waste = await handle({ method: "POST", path: "/batches/1/waste", headers: ANNEX, body: { qty: 1 } });
+  assert.equal(waste.status, 404);
+});
+
+test("receiving into another site's location is refused", async () => {
+  const { handle } = app();
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, body: { lots: [{ lot: "X", expires: null, location: "annex-fridge" }] } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_location");
+});
+
+test("cooking uses only the request's site", async () => {
+  const { handle, store } = app();
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: ANNEX, body: { portions: 1 } });
+  assert.equal(res.status, 409);
+  assert.equal(res.body.error.code, "not_enough_stock");
+  const batch = await stockAnnex(handle);
+  const movements = store.data.movements.length;
+  const cooked = await handle({ method: "POST", path: "/recipes/1/cook", headers: ANNEX, body: { portions: 1 } });
+  assert.equal(cooked.status, 409);
+  assert.equal(store.data.movements.length, movements);
+  assert.equal(store.data.batches.find((b) => b.id === batch.id).qty, 3);
+});
+
+test("alerts and stock value only see the request's site", async () => {
+  const { handle } = app();
+  const empty = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(empty.expiring, []);
+  assert.equal(empty.lowStock.length, 6);
+  assert.deepEqual((await handle({ path: "/reports/stock-value", headers: ANNEX })).body.totalCents, 0);
+  const batch = await stockAnnex(handle);
+  const alerts = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.id), [batch.id]);
+  assert.ok(!(await handle({ path: "/alerts" })).body.expiring.some((b) => b.id === batch.id));
+  const value = (await handle({ path: "/reports/stock-value", headers: ANNEX })).body;
+  assert.equal(value.totalCents, 3 * 180);
+  const main = (await handle({ path: "/reports/stock-value" })).body;
+  assert.equal(main.lines.find((l) => l.itemId === 1).qty, 10);
+});
+
+test("stock-takes only see the request's site", async () => {
+  const { handle } = app();
+  const wrong = await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "dry" } });
+  assert.equal(wrong.status, 400);
+  assert.equal(wrong.body.error.code, "unknown_location");
+  const batch = await stockAnnex(handle);
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: batch.id, counted: 2 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: ANNEX, body: { batchId: batch.id, counted: 2 } })).status, 200);
+  const res = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: ANNEX });
+  assert.deepEqual(res.body.lines, [{ batchId: batch.id, expected: 3, counted: 2, diff: -1 }]);
+});
+
+test("items, recipes and dishes are shared", async () => {
+  const { handle } = app();
+  for (const path of ["/items/1", "/dishes", "/suppliers", "/recipes/1/cost"]) {
+    assert.deepEqual((await handle({ path, headers: ANNEX })).status, 200);
+  }
+  assert.deepEqual((await handle({ path: "/dishes", headers: ANNEX })).body, (await handle({ path: "/dishes" })).body);
+});
+
+test("the nightly job queues low stock per site", async () => {
+  const { handle, store } = app();
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  await handle({ method: "POST", path: "/jobs/nightly", headers: ANNEX });
+  const low = store.data.outbox.filter((m) => m.kind === "low_stock");
+  assert.equal(low.length, 1);
+  assert.equal(low[0].key, "low:annex:2026-10-28");
+  assert.match(low[0].subject, /^6 items below minimum at annex$/);
+});
